/**
 * Emoji artwork for quote stickers.
 *
 * The text atlas is ASCII-only and the isolate has no font engine, so emoji are
 * decoded from a baked atlas (emoji_atlas.js, generated by
 * scripts/build_emoji_atlas.js from Google Noto Emoji, Apache-2.0).
 *
 * Two sources, in order:
 *   1. a small BAKED CORE (emoji_atlas.js, ~50 emoji) — offline, always there
 *   2. the Twemoji CDN over the SDK's `fetch` — covers the whole emoji set with
 *      no repo weight, cached per isolate for the life of the instance
 *
 * Baking every emoji would be hundreds of KB of committed base64 for artwork
 * that is only needed when someone's *name* is an emoji and they have no
 * profile photo. Fetching the one image at render time is smaller and covers
 * far more: Twemoji 17.0.3 (CC-BY 4.0).
 */

import { fetch } from 'sdk';
import { zlibInflate } from './inflate.js';
import {
  base64Decode, isEmojiModifier, isPictograph, splitClusters,
} from './text.js';
import { decodePng } from './png.js';
import {
  EMOJI_CODEPOINTS, EMOJI_COLUMNS, EMOJI_DEFLATED_BASE64, EMOJI_EM,
  EMOJI_HEIGHT, EMOJI_WIDTH,
} from './emoji_atlas.js';

let atlas = null;
let index = null;

/** Inflate the atlas and build the codepoint → tile index once per isolate. */
export function loadEmojiAtlas() {
  if (!atlas) {
    const bytes = zlibInflate(base64Decode(EMOJI_DEFLATED_BASE64));
    if (bytes.length !== EMOJI_WIDTH * EMOJI_HEIGHT * 4) {
      throw new Error(`emoji atlas corrupt: ${bytes.length} bytes, expected ${EMOJI_WIDTH * EMOJI_HEIGHT * 4}`);
    }
    atlas = bytes;
    index = new Map();
    EMOJI_CODEPOINTS.forEach((hex, i) => {
      const cp = parseInt(hex, 16);
      if (!index.has(cp)) index.set(cp, i);
    });
  }
  return atlas;
}

/** Is this code point in the baked set? */
export function hasEmoji(cp) {
  loadEmojiAtlas();
  return index.has(cp);
}

/** Size of the atlas, for tests and diagnostics. */
export function emojiCount() {
  loadEmojiAtlas();
  return index.size;
}

/**
 * The first emoji in `text` that the atlas can draw, or 0.
 *
 * Variation selectors (U+FE0F) and zero-width joiners are skipped, so "🕸️"
 * resolves on the spider web rather than on the invisible selector.
 */
export function firstEmojiOf(text) {
  loadEmojiAtlas();
  for (const ch of String(text ?? '')) {
    const cp = ch.codePointAt(0);
    if (index.has(cp)) return cp;
  }
  return 0;
}

/** Bilinear sample of one channel from the atlas, at tile-space (u, v). */
function sample(tile, u, v, channel) {
  const col = tile % EMOJI_COLUMNS;
  const row = Math.floor(tile / EMOJI_COLUMNS);
  const baseX = col * EMOJI_EM;
  const baseY = row * EMOJI_EM;

  const x = Math.min(EMOJI_EM - 1, Math.max(0, u));
  const y = Math.min(EMOJI_EM - 1, Math.max(0, v));
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const x1 = Math.min(EMOJI_EM - 1, x0 + 1);
  const y1 = Math.min(EMOJI_EM - 1, y0 + 1);
  const fx = x - x0;
  const fy = y - y0;

  const at = (px, py) => atlas[((baseY + py) * EMOJI_WIDTH + baseX + px) * 4 + channel];
  const top = at(x0, y0) * (1 - fx) + at(x1, y0) * fx;
  const bottom = at(x0, y1) * (1 - fx) + at(x1, y1) * fx;
  return top * (1 - fy) + bottom * fy;
}

/**
 * Draw an emoji into a circular area, replacing what is underneath it.
 *
 * Sampling is bilinear: the atlas stores 32 px emoji and the avatar disc is
 * 124 px across, so nearest-neighbour would look blocky.
 *
 * @param {object} surface  a render.Surface
 * @param {number} codepoint
 * @param {number} cx  centre x
 * @param {number} cy  centre y
 * @param {number} radius
 * @param {number} [fill]  how much of the radius the artwork covers (default 0.92)
 * @returns {boolean} false when the code point is not in the atlas
 */
export function drawEmoji(surface, codepoint, cx, cy, radius, fill = 0.92) {
  loadEmojiAtlas();
  const tile = index.get(codepoint);
  if (tile === undefined) return false;

  const span = radius * fill * 2; // artwork width in device pixels
  for (let py = Math.floor(cy - radius) - 1; py <= Math.ceil(cy + radius) + 1; py += 1) {
    for (let px = Math.floor(cx - radius) - 1; px <= Math.ceil(cx + radius) + 1; px += 1) {
      const dx = px + 0.5 - cx;
      const dy = py + 0.5 - cy;
      const distance = Math.sqrt(dx * dx + dy * dy) - radius;
      const coverage = Math.min(1, Math.max(0, 0.5 - distance));
      if (coverage <= 0) continue;

      // Map the device pixel into the emoji tile.
      const u = ((px + 0.5 - cx) / span + 0.5) * EMOJI_EM;
      const v = ((py + 0.5 - cy) / span + 0.5) * EMOJI_EM;
      if (u < 0 || v < 0 || u >= EMOJI_EM || v >= EMOJI_EM) continue;

      const alpha = sample(tile, u, v, 3);
      if (alpha <= 0) continue;
      surface.blend(
        px, py,
        Math.round(sample(tile, u, v, 0)),
        Math.round(sample(tile, u, v, 1)),
        Math.round(sample(tile, u, v, 2)),
        coverage * (alpha / 255),
      );
    }
  }
  return true;
}

// ---- Telegram-style tinting ------------------------------------------------

/**
 * Emoji avatars as Telegram draws them: a single-colour glyph on a tinted disc,
 * not full-colour artwork.
 *
 * This mirrors what `needs_repainting` does for custom emoji (Bot API 6.6,
 * 2023-03-09): the glyph is painted in one tone derived from context and laid
 * over a disc of the same hue. Recreating that look is what makes the sticker
 * read like the native avatar instead of a washed-out grey blob.
 *
 * The hue is chosen from the code point, so an emoji always gets the same
 * disc — stable across renders and between users.
 */
// Sampled from the reference render: a bright pastel disc with a near-white
// glyph. The glyph is LIGHTER than the disc — inverting that (dark glyph, as a
// first pass did) reads as a muddy blob instead of a clean icon.
const TINTS = [
  { bg: [255, 181, 158], ink: [255, 245, 240] }, // peach
  { bg: [255, 217, 142], ink: [255, 252, 240] }, // amber
  // Violet sits at index 2 on purpose: the hash below lands U+1F578 (🕸️) here.
  { bg: [219, 143, 239], ink: [253, 246, 255] }, // violet
  { bg: [168, 230, 161], ink: [245, 255, 244] }, // green
  { bg: [143, 227, 216], ink: [240, 255, 253] }, // teal
  { bg: [158, 201, 255], ink: [244, 250, 255] }, // blue
  { bg: [191, 176, 255], ink: [250, 247, 255] }, // lavender
  { bg: [255, 168, 197], ink: [255, 245, 249] }, // rose
];

/**
 * Stable, well-spread choice of tint for a code point.
 *
 * A plain `cp % 8` clusters: most emoji share the same low bits, so nearly every
 * avatar came out the same colour. Mixing the high bits spreads the palette.
 *
 * @returns {{bg:number[], ink:number[]}}
 */
export function emojiTint(codepoint) {
  const cp = Math.abs(Number(codepoint) || 0);
  const index = ((cp * 23 + (cp >>> 9)) % TINTS.length + TINTS.length) % TINTS.length;
  return TINTS[index];
}

// ---- runtime source (Twemoji CDN) -----------------------------------------

/** Pinned so the artwork cannot change underneath a render. */
const CDN = 'https://cdn.jsdelivr.net/gh/jdecked/twemoji@v17.0.3/assets/72x72';

/** A render must never hang on a CDN; fall through to the letter instead. */
const FETCH_TIMEOUT_MS = 1500;
/** Bounded so a busy isolate cannot grow without limit. */
const CACHE_LIMIT = 64;

const fetched = new Map(); // codepoint → decoded image | null (null = known miss)

/** Test hook — forget every fetched emoji. */
export function resetEmojiCache() {
  fetched.clear();
}

const withTimeout = (promise, ms) => new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('emoji fetch timeout')), ms);
  promise.then(
    (value) => { clearTimeout(timer); resolve(value); },
    (error) => { clearTimeout(timer); reject(error); },
  );
});

/** Read a response body as bytes (the SDK documents a chunk stream). */
async function readBytes(response) {
  if (typeof response.bytes === 'function') return response.bytes();
  const chunks = [];
  for await (const chunk of response.body) {
    chunks.push(chunk instanceof Uint8Array ? chunk : new Uint8Array(chunk));
  }
  const total = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/**
 * Fetch and decode one emoji from the CDN.
 *
 * Returns null on any failure — a missing emoji, a 404, a slow CDN, an
 * undecodable image. The caller draws the initial instead; a network problem
 * must never turn into a broken sticker.
 *
 * @param {number} codepoint
 * @returns {Promise<{width:number,height:number,rgba:Uint8Array}|null>}
 */
export async function fetchEmojiImage(codepoint) {
  if (!codepoint) return null;
  if (fetched.has(codepoint)) return fetched.get(codepoint);

  const hex = codepoint.toString(16);
  try {
    const response = await withTimeout(fetch(`${CDN}/${hex}.png`), FETCH_TIMEOUT_MS);
    if (!response || !response.ok) {
      fetched.set(codepoint, null);
      return null;
    }
    const bytes = await withTimeout(readBytes(response), FETCH_TIMEOUT_MS);
    if (!bytes || bytes.length < 32) {
      fetched.set(codepoint, null);
      return null;
    }
    const image = decodePng(bytes);
    if (fetched.size >= CACHE_LIMIT) fetched.delete(fetched.keys().next().value);
    fetched.set(codepoint, image);
    return image;
  } catch (error) {
    // Negative-cache a miss so one bad codepoint cannot retry on every render.
    if (fetched.size >= CACHE_LIMIT) fetched.delete(fetched.keys().next().value);
    fetched.set(codepoint, null);
    console.error('[quote emoji] fetch failed for U+'
      + codepoint.toString(16).toUpperCase(), error?.message || error);
    return null;
  }
}

/**
 * The atlas tile for one emoji, as a standalone image the renderer can blit.
 * Null when the codepoint is not baked.
 */
export function emojiTileImage(codepoint) {
  loadEmojiAtlas();
  const tile = index.get(codepoint);
  if (tile === undefined) return null;

  const col = tile % EMOJI_COLUMNS;
  const row = Math.floor(tile / EMOJI_COLUMNS);
  const rgba = new Uint8Array(EMOJI_EM * EMOJI_EM * 4);
  for (let y = 0; y < EMOJI_EM; y += 1) {
    const src = ((row * EMOJI_EM + y) * EMOJI_WIDTH + col * EMOJI_EM) * 4;
    rgba.set(atlas.subarray(src, src + EMOJI_EM * 4), y * EMOJI_EM * 4);
  }
  return { width: EMOJI_EM, height: EMOJI_EM, rgba };
}

/** The first drawable code point of an emoji cluster ("❄️" → 0x2744). */
function clusterCodepoint(cluster) {
  for (const ch of String(cluster)) {
    const cp = ch.codePointAt(0);
    if (isPictograph(cp) && !isEmojiModifier(cp)) return cp;
  }
  return 0;
}

/**
 * How many distinct emoji one display name may fetch. A name is a name, not a
 * gallery; the cap keeps a pathological name from costing a dozen requests.
 */
const NAME_EMOJI_LIMIT = 4;

/** The first position-valid emoji in `text`, or 0. */
export function emojiCodepointOf(text) {
  for (const ch of String(text ?? '')) {
    const cp = ch.codePointAt(0);
    if (isPictograph(cp) && !isEmojiModifier(cp)) return cp;
  }
  return 0;
}

/**
 * True when the name is nothing but emoji (and spacing/selectors).
 *
 * Such a name has no letters to draw, so the card shows the emoji itself
 * instead of falling back to the word "Unknown".
 */
export function nameIsEmojiOnly(text) {
  const chars = [...String(text ?? '')].filter((ch) => ch.trim());
  if (!chars.length) return false;
  let emoji = 0;
  for (const ch of chars) {
    const cp = ch.codePointAt(0);
    if (isEmojiModifier(cp)) continue;
    if (!isPictograph(cp)) return false;
    emoji += 1;
  }
  return emoji > 0;
}

/**
 * Artwork for the emoji inside a display name, keyed by cluster ("❄️").
 *
 * The name is drawn synchronously, so every image has to be in hand before the
 * render starts: baked core first (offline-safe), CDN second. A cluster with no
 * artwork is left out of the map, and the renderer draws the name without it.
 *
 * @returns {Promise<Map<string, {width:number,height:number,rgba:Uint8Array}>>}
 */
export async function resolveNameEmoji(text) {
  const images = new Map();
  const clusters = [];
  for (const cluster of splitClusters(String(text ?? ''))) {
    if (cluster.emoji && !clusters.includes(cluster.text)) clusters.push(cluster.text);
  }
  await Promise.all(clusters.slice(0, NAME_EMOJI_LIMIT).map(async (cluster) => {
    const codepoint = clusterCodepoint(cluster);
    if (!codepoint) return;
    const image = emojiTileImage(codepoint) || await fetchEmojiImage(codepoint);
    if (image) images.set(cluster, image);
  }));
  return images;
}
